 perform 1 from public.marketing_calendar_plans where id='noviembre-2026' for update;
 if (select meta->>'stories_revision' from public.marketing_calendar_plans where id='noviembre-2026')='15-individual-stories-v3' then return; end if;
 if not exists(select 1 from public.marketing_calendar_plans where id='noviembre-2026' and meta='{"end": "2026-12-06", "scope": "5 reels (4 orgánicos + 1 adicional para pauta Meta) + 15 posts de feed. Solo 2 rodajes: jueves 5/11 confirmado y jueves 19/11 propuesto. 34 secuencias de stories hasta el 6/12, adicionales al feed. Horarios propuestos; el calendario no publica ni activa pauta.", "start": "2026-11-01", "title": "Calendario comercial · noviembre 2026", "edition": "2026-11-03", "sources": [{"url": "https://about.fb.com/news/2024/10/best-practices-education-hub-creators-instagram/", "title": "Meta · Best Practices de Instagram", "finding": "Meta organiza recomendaciones de creación, interacción y alcance y ofrece consejos personalizados en el panel profesional. Sustenta revisar Insights propios, sin afirmar una hora universal."}, {"url": "https://about.fb.com/news/2024/12/trial-reels-try-content-non-followers-first-see-what-perfoms-best/", "title": "Meta · Trial Reels", "finding": "Meta describe pruebas con no seguidores para explorar formatos. Si la función aparece en la cuenta, usarla en R01 o R03; mantener R02 y R04 en el calendario normal por su vigencia. El plan ahora incluye el quinto reel de pauta autorizado por Samuel; las tomas alternativas no añaden más reels."}, {"url": "https://about.fb.com/news/2025/06/inspiring-creativity-that-brings-people-together/", "title": "Meta · Creatividad y pruebas", "finding": "Apoya experimentar con contenido y observar la respuesta. Los formatos y guiones propuestos aquí son una inferencia creativa para Importados, no un estudio de ventas de esta cuenta."}, {"url": "https://www.instagram.com/tiendasimportados/", "title": "Instagram de Importados · revisión manual pendiente", "finding": "Fuente propia a contrastar por el equipo; no se pudo auditar el feed actual desde esta sesión."}], "strategy": [{"body": "R01: recorrido POV local. R02: invitación orgánica breve de tres motivos. R03: antes/después navideño. R04: lista navideña/Black Friday. R05: anuncio adicional de inauguración con todas las dinámicas, pensado para Meta Ads y publicado el 9/11 antes del evento. Son hipótesis creativas para la tienda, sin promesa de viralidad.", "title": "Cinco reels, funciones distintas"}, {"body": "Natillada y ubicación generan confianza; invitación y cobertura llevan a la inauguración; memoria del evento valida la experiencia; guías y lista preparan Black Friday; diciembre vuelve a inspiración sin prolongar el 20 %.", "title": "Una campaña que acumula intención"}, {"body": "Solo dos rodajes profesionales. Jueves 5/11 confirmado: R01, R02, R05 y banco fotográfico/recursos de inauguración y primera selección navideña. Jueves 19/11 propuesto: R03, R04 y banco de Navidad/Black Friday para el cierre. Horario sugerido 09:00–14:00 ambos días. El resto es edición, diseño y programación; no hay rodajes el 4, 9, 16 o 23. Para memorias de eventos, usar material existente/espontáneo compartido por tienda o agradecimientos gráficos; no fingir cobertura. Video propio vertical, voz, subtítulos y música apta para uso comercial.", "title": "Grabación que se puede ejecutar"}, {"body": "Feed entre semana 18:30; sábado de lista/selección 11:30; anuncios de inicio 08:30/09:00. Stories en tres ventanas, con cobertura extra en eventos. America/Bogota. Ajustar con Insights propios tras dos semanas: no tenemos métricas actuales de la cuenta. R03 pasa del 18 al 20/11 para editar después del segundo rodaje. R05 va el 9/11 a las 18:30. El 5/11 R01 tiene edición prioritaria para las 18:30; si no se aprueba a tiempo, reprogramar explícitamente.", "title": "Horario de partida, no «mejor hora» probada"}, {"body": "A las 24 h y 7 días: alcance, tiempo medio de reproducción y retención si están disponibles, compartidos/alcance, guardados/alcance, visitas al perfil y seguidores netos. Registrar consultas cualificadas por pieza (producto + sede + intención), visitas autodeclaradas y ventas verificadas por separado. No confundir reproducción, clic o consulta con venta.", "title": "Medición útil para retail"}, {"body": "R05 es la pieza adicional dedicada a convocatoria de inauguración: publicar el 9/11, con rodaje el 5, edición 6, revisión 7 y cierre de condiciones/aprobación 8. Propuesta de pauta 9–13/11, sin gasto ni activación desde el módulo. R02 queda orgánico para no duplicar inversión. R04 puede apoyar Black Friday si se autoriza otra campaña. Definir presupuesto, objetivo, destino y área de captación real de Niquía; comprobar bases y elegibilidad del anuncio antes de pautar premios. Medir consultas/visitas y ventas verificadas por separado, sin prometer resultados.", "title": "Pauta después de validar la pieza"}, {"body": "Las ocho fotos aportadas son referencias de licuadora, arrocera, trenes, Papá Noel, detalles dorados/plateados y árboles. Las etiquetas fotografiadas no son autorización para anunciar precios ni aplicarles otro descuento. Solicitar un inventario visual adicional de Navidad; mostrar luces, bolas, guirnaldas o empaques solo si se confirma que se venden.", "title": "Productos reales, no catálogo cerrado"}, {"body": "Se intentó revisar el perfil público y su embed el 3/11/2026: Instagram bloqueó la lectura automatizada y la búsqueda no recuperó publicaciones verificables. No se atribuyen métricas, frecuencia ni piezas recientes a la cuenta. El material previamente compartido muestra fachada, presentadora y estética amarilla/negra; se mantiene esa continuidad. Antes de producir, el equipo debe contrastar los 19 temas con el feed real y evitar duplicados.", "title": "Revisión de Instagram: alcance y límite"}, {"body": "Inauguración: 20 % en casi toda la tienda, sin transformarlo en «toda». Black Friday: 20 % en toda la tienda 27–29, pendiente de condiciones finales. Rifa: compra y seguir Instagram confirmados; faltan bases. Concurso: dos componentes de $500.000, sin sumar como efectivo. Artista: imitadora de Arelys Henao, sin aparentar contratación de la cantante original. Horarios de shows sin definir.", "title": "Promociones con información clara"}], "timezone": "America/Bogota", "production_revision": "two-shoots-v2"}'::jsonb) then raise exception 'Calendar strategy changed; review stories update'; end if;
 perform 1 from public.marketing_calendar_items where id='S1103' and plan_id='noviembre-2026' and revision=2 and data-'revision'='{"id": "S1103", "date": "2026-11-03", "kind": "story", "time": "10:30", "title": "Tu Navidad empieza a tomar forma", "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "format": "Secuencia · 3 stories · 1080 × 1920", "script": [], "season": "niquia", "status": "planned", "caption": "10:30 · Foto de producto real: «¿Ya empezaste a pensar en Navidad?»\n13:00 · Encuesta: «¿Árbol primero o detalles primero?»\n18:30 · Fachada + dirección Niquía y enlace a ubicación.", "outline": ["10:30 · Foto de producto real: «¿Ya empezaste a pensar en Navidad?»", "13:00 · Encuesta: «¿Árbol primero o detalles primero?»", "18:30 · Fachada + dirección Niquía y enlace a ubicación."], "end_date": "2026-11-03", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al plan de 5 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra. Usar recursos de los rodajes 5/11 y 19/11 (segundo propuesto). La actualidad del evento solo se muestra si tienda aporta material espontáneo real; no se programa un rodaje adicional."}'::jsonb for update;
 if not found then raise exception 'Story changed: S1103'; end if;
