 update public.marketing_calendar_items set data='{"id": "S1109", "date": "2026-11-09", "time": "18:45", "end_date": "2026-11-09", "kind": "story", "season": "niquia", "title": "Comparte el plan de inauguración", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "14 y 15 de noviembre: tenemos plan en Niquía 💛🖤\nMira todas las dinámicas y consulta las bases.", "outline": ["Recompartir R05 en una sola story, tras su aprobación. Añadir «14 y 15 de noviembre · ¿con quién vienes?» y enlace a programación/bases aprobadas. No presentarlo como anuncio pagado activo."], "assets": [], "checks": ["R05 publicado y aprobado; bases de rifa/concurso, condiciones del descuento y enlace accesible antes de compartir."], "script": [], "format": "Recompartido de R05 · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1109' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1112", "date": "2026-11-12", "time": "18:30", "end_date": "2026-11-12", "kind": "story", "season": "niquia", "title": "Rifa de inauguración: cómo participar", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "Rifa de inauguración 💛\nCompra en tienda + sigue @tiendasimportados\nConsulta requisitos y bases completas antes de participar.", "outline": ["Una sola pieza con foto real autorizada de premios. Texto «Rifa de moto AKT y patinetes eléctricos / Compra en tienda + sigue @tiendasimportados». Sticker a bases completas aprobadas y fechas 14/15. No resumir como único requisito si las bases incluyen más condiciones."], "assets": [], "checks": ["Aprobar bases completas, modelos/cantidades de premios, requisitos, sorteo y entrega; foto real o arte autorizado. No publicar sin bases accesibles."], "script": [], "format": "Imagen de promoción · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1112' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1113", "date": "2026-11-13", "time": "18:30", "end_date": "2026-11-13", "kind": "story", "season": "niquia", "title": "Mañana empieza la gran inauguración", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "¡Mañana empieza la celebración! 💛\n14 y 15 de noviembre · Importados Niquía\nEdificio Valkiria · Diagonal 55 Av 38-33", "outline": ["Una sola pieza de fachada/presentador del rodaje 1. Texto «¡Mañana! / 14 y 15 NOV / Niquía · edificio Valkiria» y enlace a ubicación. No anunciar hora de artistas sin confirmación."], "assets": [], "checks": [], "script": [], "format": "Imagen o clip corto · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1113' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1114", "date": "2026-11-14", "time": "08:45", "end_date": "2026-11-14", "kind": "story", "season": "niquia", "title": "Es hoy: inauguración Niquía", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "¡Es hoy, Niquía! 💛🖤\nGran inauguración · 14 y 15 de noviembre\nConsulta aquí la programación.", "outline": ["Una sola story con fachada del banco del 5/11 y texto «¡Es hoy! Gran inauguración · 14 y 15 NOV». Dirección clara y enlace a programación confirmada. No simular cobertura en vivo."], "assets": [], "checks": ["Enlazar programación solo si está confirmada; en caso contrario, usar enlace a ubicación."], "script": [], "format": "Imagen de apertura · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1114' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1115", "date": "2026-11-15", "time": "09:00", "end_date": "2026-11-15", "kind": "story", "season": "niquia", "title": "La celebración sigue en Niquía", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "¡Hoy seguimos de inauguración! 💛\nTe esperamos en Importados Niquía\nDiagonal 55 Av 38-33 · edificio Valkiria", "outline": ["Una sola imagen del banco de fachada/equipo o foto espontánea autorizada del 14. Texto «Hoy seguimos de inauguración» y enlace a ubicación. Si es del banco, no presentarla como cobertura de ayer."], "assets": [], "checks": ["Verificar programación real del día 15 si se menciona alguna actividad; permisos si aparece público."], "script": [], "format": "Imagen de segundo día · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1115' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1117", "date": "2026-11-17", "time": "18:30", "end_date": "2026-11-17", "kind": "story", "season": "navidad", "title": "Gracias, Niquía", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "¡Gracias por celebrar con nosotros, Niquía! 💛🖤\nSeguimos aquí para acompañarte.", "outline": ["Una sola foto autorizada del evento que aporte la tienda. Alternativa sin cobertura: agradecimiento gráfico con fachada del banco y sin aparentar que es una foto del evento. No añadir recap en varias stories."], "assets": [], "checks": ["Validar foto/permisos; no anunciar ganadores ni resultados no confirmados."], "script": [], "format": "Imagen de agradecimiento · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1117' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1120", "date": "2026-11-20", "time": "18:45", "end_date": "2026-11-20", "kind": "story", "season": "navidad", "title": "El antes y después de tu rincón navideño", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "Una idea para tu rincón de Navidad 🎄\n¿Dorado o plateado?", "outline": ["Recompartir R03 en una sola story, con texto «Una idea para tu rincón de Navidad» y encuesta «¿Dorado o plateado?». Usar el reel aprobado, sin crear otra secuencia de montaje."], "assets": [], "checks": ["R03 aprobado y publicado; confirmar referencias disponibles antes de responder consultas."], "script": [], "format": "Recompartido de R03 · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1120' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1124", "date": "2026-11-24", "time": "18:30", "end_date": "2026-11-24", "kind": "story", "season": "black-friday", "title": "Agenda Black Friday: 27 al 29", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "27, 28 y 29 de noviembre 🖤💛\nBlack Friday · 20 % en toda la tienda\nConsulta condiciones y prepara tu lista.", "outline": ["Una sola pieza con fotos seleccionadas del rodaje 2, fechas 27–29 noviembre, «20 % en toda la tienda» y enlace a condiciones completas. Sin precios de etiqueta no validados."], "assets": [], "checks": ["Confirmar condiciones finales del 20 %, sedes, precio base y vigencia; tener enlace accesible."], "script": [], "format": "Imagen de expectativa · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1124' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1126", "date": "2026-11-26", "time": "18:45", "end_date": "2026-11-26", "kind": "story", "season": "black-friday", "title": "Mañana empieza Black Friday", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "¡Mañana empieza Black Friday! 🖤💛\n27 al 29 de noviembre\nConsulta tus favoritos y las condiciones.", "outline": ["Recompartir R04 aprobado en una sola story. Añadir «Mañana empieza / 27–29 NOV» y enlace a WhatsApp para consultar referencias. Mantener condiciones accesibles en la publicación vinculada."], "assets": [], "checks": ["R04 aprobado y publicado; validar condiciones del 20 % y vigencia."], "script": [], "format": "Recompartido de R04 · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1126' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1127", "date": "2026-11-27", "time": "08:45", "end_date": "2026-11-27", "kind": "story", "season": "black-friday", "title": "Hoy empieza Black Friday", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "¡Black Friday empieza hoy! 🖤💛\n20 % en toda la tienda · 27 al 29 de noviembre\nConsulta disponibilidad y condiciones.", "outline": ["Una sola story de selección navideña del banco del rodaje 2. Texto «Empieza hoy / 20 % en toda la tienda / 27–29 NOV». Enlace a condiciones o WhatsApp, sin prometer stock."], "assets": [], "checks": ["Condiciones de promoción aprobadas; revisar existencias de productos visibles ese día."], "script": [], "format": "Imagen de promoción · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1127' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1129", "date": "2026-11-29", "time": "09:00", "end_date": "2026-11-29", "kind": "story", "season": "black-friday", "title": "Último día de Black Friday", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "¡Hoy termina Black Friday! 🖤💛\n29 de noviembre · 20 % en toda la tienda\nConsulta condiciones y horario de atención.", "outline": ["Una sola imagen de referencia disponible. Texto «Hoy, 29 de noviembre / Último día / 20 % en toda la tienda», condiciones legibles y enlace a consulta. No usar una cuenta atrás ni horario de cierre sin confirmar."], "assets": [], "checks": ["Confirmar horario de domingo y hora de cierre de la promoción; revisar condiciones/existencias."], "script": [], "format": "Imagen de cierre · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1129' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1201", "date": "2026-12-01", "time": "18:30", "end_date": "2026-12-01", "kind": "story", "season": "navidad", "title": "Hola, diciembre", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "¡Hola, diciembre! 🎄💛\n¿Qué te falta para decorar tu casa?", "outline": ["Una sola composición navideña del rodaje 2 con «Hola, diciembre 🎄 / ¿Qué te falta para decorar?» y caja de preguntas. Sin rótulos del 20 %, que terminó el 29/11."], "assets": [], "checks": ["Comprobar referencias disponibles; retirar cualquier descuento vencido del diseño."], "script": [], "format": "Imagen de Navidad · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1201' and plan_id='noviembre-2026';
 delete from public.marketing_calendar_items where plan_id='noviembre-2026' and id in ('S1103','S1107','S1108','S1110','S1111','S1116','S1118','S1119','S1121','S1122','S1123','S1125','S1128','S1130','S1202','S1203','S1204','S1205','S1206');
 update public.marketing_calendar_plans set meta='{"title": "Calendario comercial · noviembre 2026", "edition": "2026-11-03", "timezone": "America/Bogota", "start": "2026-11-01", "end": "2026-12-06", "scope": "5 reels (4 orgánicos + 1 adicional para pauta Meta) + 15 posts de feed + 15 stories individuales en total. Solo 2 rodajes: jueves 5/11 confirmado y jueves 19/11 propuesto. Cada story es una sola pieza, no una secuencia diaria. Horarios propuestos; el calendario no publica ni activa pauta.", "strategy": [{"title": "Cinco reels, funciones distintas", "body": "R01: recorrido POV local. R02: invitación orgánica breve de tres motivos. R03: antes/después navideño. R04: lista navideña/Black Friday. R05: anuncio adicional de inauguración con todas las dinámicas, pensado para Meta Ads y publicado el 9/11 antes del evento. Son hipótesis creativas para la tienda, sin promesa de viralidad."}, {"title": "Una campaña que acumula intención", "body": "Natillada y ubicación generan confianza; invitación y cobertura llevan a la inauguración; memoria del evento valida la experiencia; guías y lista preparan Black Friday; diciembre vuelve a inspiración sin prolongar el 20 %."}, {"title": "Grabación que se puede ejecutar", "body": "Solo dos rodajes profesionales. Jueves 5/11 confirmado: R01, R02, R05 y banco fotográfico/recursos de inauguración y primera selección navideña. Jueves 19/11 propuesto: R03, R04 y banco de Navidad/Black Friday para el cierre. Horario sugerido 09:00–14:00 ambos días. El resto es edición, diseño y programación; no hay rodajes el 4, 9, 16 o 23. Para memorias de eventos, usar material existente/espontáneo compartido por tienda o agradecimientos gráficos; no fingir cobertura. Video propio vertical, voz, subtítulos y música apta para uso comercial. Las 15 stories se producen con ese mismo banco: una sola pieza por entrada del calendario. No se requieren 34 días de cobertura ni tres publicaciones diarias."}, {"title": "Horario de partida, no «mejor hora» probada", "body": "Feed entre semana 18:30; sábado de lista/selección 11:30; anuncios de inicio 08:30/09:00. Solo 15 stories individuales en fechas seleccionadas: natillada, ubicación, inauguración, expectativa/venta de Black Friday y Navidad. No se incluyen secuencias diarias ni cobertura adicional como entregables. America/Bogota. Ajustar con Insights propios tras dos semanas: no tenemos métricas actuales de la cuenta. R03 pasa del 18 al 20/11 para editar después del segundo rodaje. R05 va el 9/11 a las 18:30. El 5/11 R01 tiene edición prioritaria para las 18:30; si no se aprueba a tiempo, reprogramar explícitamente."}, {"title": "Medición útil para retail", "body": "A las 24 h y 7 días: alcance, tiempo medio de reproducción y retención si están disponibles, compartidos/alcance, guardados/alcance, visitas al perfil y seguidores netos. Registrar consultas cualificadas por pieza (producto + sede + intención), visitas autodeclaradas y ventas verificadas por separado. No confundir reproducción, clic o consulta con venta."}, {"title": "Pauta después de validar la pieza", "body": "R05 es la pieza adicional dedicada a convocatoria de inauguración: publicar el 9/11, con rodaje el 5, edición 6, revisión 7 y cierre de condiciones/aprobación 8. Propuesta de pauta 9–13/11, sin gasto ni activación desde el módulo. R02 queda orgánico para no duplicar inversión. R04 puede apoyar Black Friday si se autoriza otra campaña. Definir presupuesto, objetivo, destino y área de captación real de Niquía; comprobar bases y elegibilidad del anuncio antes de pautar premios. Medir consultas/visitas y ventas verificadas por separado, sin prometer resultados."}, {"title": "Productos reales, no catálogo cerrado", "body": "Las ocho fotos aportadas son referencias de licuadora, arrocera, trenes, Papá Noel, detalles dorados/plateados y árboles. Las etiquetas fotografiadas no son autorización para anunciar precios ni aplicarles otro descuento. Solicitar un inventario visual adicional de Navidad; mostrar luces, bolas, guirnaldas o empaques solo si se confirma que se venden."}, {"title": "Revisión de Instagram: alcance y límite", "body": "Se intentó revisar el perfil público y su embed el 3/11/2026: Instagram bloqueó la lectura automatizada y la búsqueda no recuperó publicaciones verificables. No se atribuyen métricas, frecuencia ni piezas recientes a la cuenta. El material previamente compartido muestra fachada, presentadora y estética amarilla/negra; se mantiene esa continuidad. Antes de producir, el equipo debe contrastar los 19 temas con el feed real y evitar duplicados."}, {"title": "Promociones con información clara", "body": "Inauguración: 20 % en casi toda la tienda, sin transformarlo en «toda». Black Friday: 20 % en toda la tienda 27–29, pendiente de condiciones finales. Rifa: compra y seguir Instagram confirmados; faltan bases. Concurso: dos componentes de $500.000, sin sumar como efectivo. Artista: imitadora de Arelys Henao, sin aparentar contratación de la cantante original. Horarios de shows sin definir."}], "sources": [{"title": "Meta · Best Practices de Instagram", "url": "https://about.fb.com/news/2024/10/best-practices-education-hub-creators-instagram/", "finding": "Meta organiza recomendaciones de creación, interacción y alcance y ofrece consejos personalizados en el panel profesional. Sustenta revisar Insights propios, sin afirmar una hora universal."}, {"title": "Meta · Trial Reels", "url": "https://about.fb.com/news/2024/12/trial-reels-try-content-non-followers-first-see-what-perfoms-best/", "finding": "Meta describe pruebas con no seguidores para explorar formatos. Si la función aparece en la cuenta, usarla en R01 o R03; mantener R02 y R04 en el calendario normal por su vigencia. El plan ahora incluye el quinto reel de pauta autorizado por Samuel; las tomas alternativas no añaden más reels."}, {"title": "Meta · Creatividad y pruebas", "url": "https://about.fb.com/news/2025/06/inspiring-creativity-that-brings-people-together/", "finding": "Apoya experimentar con contenido y observar la respuesta. Los formatos y guiones propuestos aquí son una inferencia creativa para Importados, no un estudio de ventas de esta cuenta."}, {"title": "Instagram de Importados · revisión manual pendiente", "url": "https://www.instagram.com/tiendasimportados/", "finding": "Fuente propia a contrastar por el equipo; no se pudo auditar el feed actual desde esta sesión."}], "production_revision": "two-shoots-v2", "stories_revision": "15-individual-stories-v3"}'::jsonb where id='noviembre-2026';
end $calendar$;
commit;
